// Rule-based insights. Deliberately NOT generated by an AI model, and each rule states the minimum data it
// needs. When data is insufficient the rule is "withheld" with a reason instead of producing a guess.
import type { Dataset, Settings } from "./types.ts";
import { addDays, shortDate } from "./dates.ts";
import {
  aggregatePace, baselineAt, countInWeek, energyBalance, estimatedExpenditure, fmtPace, isCompleteNutritionDay, lastCompletedWeeks,
  mean, present, proteinMet, slope, sortedWeights, sum, zScore,
  strengthDates,
} from "./metrics.ts";
import { diffDays } from "./dates.ts";

export interface Insight { id: string; severity: "positive" | "info" | "attention"; title: string; body: string; evidence: string }
export interface Withheld { id: string; title: string; reason: string }

const inWin = (date: string, today: string, fromDaysAgo: number, toDaysAgo: number) => date > addDays(today, -fromDaysAgo) && date <= addDays(today, -toDaysAgo);

export function computeInsights(ds: Dataset, s: Settings, today: string): { insights: Insight[]; withheld: Withheld[] } {
  const insights: Insight[] = [];
  const withheld: Withheld[] = [];
  const add = (i: Insight) => insights.push(i);
  const hold = (id: string, title: string, reason: string) => withheld.push({ id, title, reason });

  // 1) Running volume ramp
  {
    const t = "Weekly running volume";
    const last7 = ds.runs.filter((r) => inWin(r.date, today, 7, 0));
    const prior = [1, 2, 3].map((k) => ds.runs.filter((r) => inWin(r.date, today, 7 * (k + 1), 7 * k)));
    const priorRuns = prior.reduce((a, w) => a + w.length, 0);
    if (priorRuns < 4) hold("vol", t, `Needs at least 4 runs in the 3 weeks before the last 7 days (found ${priorRuns}).`);
    else {
      const prevKm = (mean(prior.map((w) => w.reduce((a, r) => a + r.distanceKm, 0))) as number);
      const km = last7.reduce((a, r) => a + r.distanceKm, 0);
      if (prevKm > 0 && km > prevKm * 1.3 && km - prevKm >= 2)
        add({ id: "vol", severity: "attention", title: "Running volume rose quickly", body: `The last 7 days (${km.toFixed(1)} km) are ${(((km / prevKm) - 1) * 100).toFixed(0)}% above your previous 3-week average (${prevKm.toFixed(1)} km). Rapid jumps are commonly linked with higher injury risk; a gradual build is the usual guidance, though no single percentage is proven.`, evidence: `Runs from ${shortDate(addDays(today, -27))} to ${shortDate(today)} (${priorRuns + last7.length} runs).` });
      else if (prevKm > 0)
        add({ id: "vol", severity: "info", title: "Running volume is changing gradually", body: `Last 7 days: ${km.toFixed(1)} km versus a ${prevKm.toFixed(1)} km average over the 3 weeks before.`, evidence: `${priorRuns + last7.length} runs in the last 4 weeks.` });
    }
  }

  // 2) Pace-to-heart-rate efficiency
  {
    const t = "Pace at a given heart rate";
    const ef = (r: Dataset["runs"][number]) => ((1000 / (r.durationSec / r.distanceKm)) * 60) / (r.avgHr as number); // metres per heartbeat
    const withHr = ds.runs.filter((r) => r.avgHr !== null); // runs without heart-rate data cannot be compared
    const cur = withHr.filter((r) => inWin(r.date, today, 28, 0));
    const prev = withHr.filter((r) => inWin(r.date, today, 56, 28));
    if (cur.length < 3 || prev.length < 3) hold("ef", t, `Needs at least 3 runs in each of the last two 4-week blocks (found ${cur.length} and ${prev.length}).`);
    else {
      const a = mean(cur.map(ef)) as number, b = mean(prev.map(ef)) as number;
      const ch = ((a - b) / b) * 100;
      const pc = aggregatePace(cur) as number, pp = aggregatePace(prev) as number;
      if (Math.abs(ch) >= 1.5)
        add({ id: "ef", severity: ch > 0 ? "positive" : "attention", title: ch > 0 ? "You are running faster per heartbeat" : "Running efficiency has slipped",
          body: `Distance covered per heartbeat is ${Math.abs(ch).toFixed(1)}% ${ch > 0 ? "higher" : "lower"} than in the previous 4 weeks (average pace ${fmtPace(pc)} vs ${fmtPace(pp)} /km). This fits ${ch > 0 ? "improving aerobic fitness" : "fatigue, heat, or a harder mix of runs"}, but it is a correlation and weather, route and sleep also move it.`,
          evidence: `${cur.length} runs vs ${prev.length} runs.` });
    }
  }

  // 3) Protein below target
  {
    const t = "Protein intake";
    const logged = ds.days.filter((d) => d.date > addDays(today, -7) && isCompleteNutritionDay(d, today) && d.protein !== undefined);
    if (logged.length < 4) hold("protein", t, `Needs at least 4 complete logged days in the last 7 (found ${logged.length}).`);
    else {
      const below = logged.filter((d) => !proteinMet(d.protein as number, s.targets.protein, s.targets.proteinMetPct)).length;
      const avg = mean(logged.map((d) => d.protein)) as number;
      if (below >= 4 && below / logged.length >= 0.6)
        add({ id: "protein", severity: "attention", title: "Protein has been below target", body: `${below} of ${logged.length} logged days were below ${s.targets.proteinMetPct}% of your ${s.targets.protein} g target (average ${avg.toFixed(0)} g). Protein supports muscle retention during fat loss.`, evidence: `${logged.length} complete logged days, ${shortDate(logged[0].date)}–${shortDate(logged[logged.length - 1].date)}.` });
    }
  }

  // 4) Sleep duration trend
  {
    const t = "Sleep duration";
    const rec = present(ds.days.filter((d) => d.date > addDays(today, -7)).map((d) => d.sleepMin));
    const earl = present(ds.days.filter((d) => inWin(d.date, today, 35, 7)).map((d) => d.sleepMin));
    if (rec.length < 5 || earl.length < 14) hold("sleep", t, `Needs ≥5 nights in the last 7 days and ≥14 nights in the 4 weeks before (found ${rec.length} and ${earl.length}).`);
    else {
      const diff = (mean(rec) as number) - (mean(earl) as number);
      if (Math.abs(diff) >= 30)
        add({ id: "sleep", severity: diff < 0 ? "attention" : "positive", title: diff < 0 ? "Sleep duration has dropped" : "Sleep duration has increased",
          body: `Average sleep over the last 7 days is ${Math.abs(diff).toFixed(0)} minutes ${diff < 0 ? "shorter" : "longer"} than your previous 4-week average (${((mean(earl) as number) / 60).toFixed(1)} h).`, evidence: `${rec.length} recent nights vs ${earl.length} earlier nights (watch-based estimate).` });
    }
  }

  // 5) Energy intake vs expenditure
  {
    const t = "Calorie intake relative to training";
    const rows = ds.days.filter((d) => d.date > addDays(today, -7)).map((d) => ({ b: energyBalance(d, today), e: estimatedExpenditure(d) })).filter((x) => x.b !== null && x.e !== null) as { b: number; e: number }[];
    if (rows.length < 5) hold("energy", t, `Needs ≥5 days with both a complete food log and watch energy data in the last 7 (found ${rows.length}).`);
    else {
      const b = mean(rows.map((r) => r.b)) as number, e = mean(rows.map((r) => r.e)) as number;
      const pct = (-b / e) * 100;
      if (pct > 25)
        add({ id: "energy", severity: "attention", title: "Intake may be low for your training", body: `Estimated deficit averages ${(-b).toFixed(0)} kcal/day (${pct.toFixed(0)}% of estimated expenditure). Both numbers are estimates, but deficits this large can compromise recovery and running quality. If you feel run-down, consider eating closer to maintenance on run days.`, evidence: `${rows.length} days with usable data.` });
      else if (pct > 5)
        add({ id: "energy", severity: "info", title: "Moderate estimated deficit", body: `Estimated deficit averages ${(-b).toFixed(0)} kcal/day (${pct.toFixed(0)}% of estimated expenditure), a range often used for gradual fat loss. Expenditure is an estimate, so confirm with your weight trend.`, evidence: `${rows.length} days with usable data.` });
    }
  }

  // 6) Training consistency
  {
    const t = "Training consistency";
    const weeks = lastCompletedWeeks(today, 8);
    const planned = s.schedule.runDays.length + s.schedule.strengthDays.length;
    if (planned === 0) hold("cons", t, "No planned sessions in your schedule (Settings → Schedule).");
    else {
      const rate = (ws: string[]) => {
        const done = sum(ws.map((w) => Math.min(planned, countInWeek(ds.runs.map((r) => r.date), w) + countInWeek(strengthDates(ds), w)))) as number;
        return (done / (planned * ws.length)) * 100;
      };
      const rec = rate(weeks.slice(4)), pre = rate(weeks.slice(0, 4));
      if (Math.abs(rec - pre) >= 10)
        add({ id: "cons", severity: rec > pre ? "positive" : "attention", title: rec > pre ? "Training consistency has improved" : "Training consistency has dropped", body: `You completed ${rec.toFixed(0)}% of planned sessions in the last 4 weeks versus ${pre.toFixed(0)}% in the 4 weeks before (${planned} planned per week).`, evidence: `8 completed weeks, planned = ${s.schedule.runDays.length} runs + ${s.schedule.strengthDays.length} strength.` });
      else add({ id: "cons", severity: "info", title: "Training consistency is steady", body: `${rec.toFixed(0)}% of planned sessions completed in the last 4 weeks (${pre.toFixed(0)}% before).`, evidence: "8 completed weeks." });
    }
  }

  // 7) Recovery signals vs personal baseline
  {
    const t = "Recovery signals";
    const n = ds.days.length;
    const rhr = ds.days.map((d) => d.restingHr), hrv = ds.days.map((d) => d.hrv);
    const flags: string[] = [];
    let enough = true;
    for (const [name, arr, dir] of [["resting heart rate", rhr, 1], ["HRV", hrv, -1]] as const) {
      const hits: number[] = [];
      for (let i = n - 3; i < n; i++) {
        const v = arr[i]; const b = baselineAt(arr, i);
        if (b === null) { enough = false; continue; }
        if (v === undefined) continue;
        const z = zScore(v, b);
        if (z !== null && z * dir > 1.5) hits.push(i);
      }
      if (hits.length >= 2) flags.push(name);
    }
    if (!enough) hold("rec", t, "Needs at least 14 values in the 28 days before each of the last 3 days to build a personal baseline.");
    else if (flags.length)
      add({ id: "rec", severity: "attention", title: `${flags.join(" and ")} outside your usual range`, body: `On at least 2 of the last 3 days, your ${flags.join(" and ")} sat more than 1.5 standard deviations ${flags.includes("HRV") && !flags.includes("resting heart rate") ? "below" : "from"} your own 28-day baseline in the "stress" direction. This can reflect hard training, poor sleep, alcohol, heat or illness; it is not a diagnosis. Consider an easier day and watch whether it settles.`, evidence: "Comparison against your own previous 28 days." });
  }

  // 8) Weight trend
  {
    const t = "Weight trend";
    const w = sortedWeights(ds.weights).filter((x) => x.date > addDays(today, -28));
    if (w.length < 4 || diffDays(w[w.length - 1].date, w[0].date) < 14) hold("weight", t, `Needs at least 4 manual weight entries spanning 14+ days in the last 28 (found ${w.length}).`);
    else {
      const sl = slope(w.map((x) => ({ x: diffDays(x.date, today), y: x.kg }))) as number;
      const perWeek = sl * 7, cur = w[w.length - 1].kg;
      const pct = (perWeek / cur) * 100;
      add({ id: "weight", severity: pct < -1 ? "attention" : "info", title: pct < -1 ? "Weight is falling quickly" : "Weight trend", body: `The 4-week trend is ${perWeek >= 0 ? "+" : "−"}${Math.abs(perWeek).toFixed(2)} kg per week (${pct >= 0 ? "+" : "−"}${Math.abs(pct).toFixed(2)}% of body weight). ${pct < -1 ? "Losing more than about 1% per week raises the chance of losing muscle; consider a smaller deficit." : "A gradual loss of up to about 1% per week is commonly suggested when you want to keep muscle."}`, evidence: `${w.length} manual entries.` });
    }
  }

  const order = { attention: 0, positive: 1, info: 2 };
  insights.sort((a, b) => order[a.severity] - order[b.severity]);
  return { insights, withheld };
}

// ---------- "Is it improving or deteriorating?" ----------
export interface TrendRow { id: string; label: string; verdict: "improving" | "declining" | "stable"; neutral: boolean; detail: string }
export function trendSummary(ds: Dataset, s: Settings, today: string): { rows: TrendRow[]; skipped: string[] } {
  const rows: TrendRow[] = [];
  const skipped: string[] = [];
  const cmp = (id: string, label: string, cur: number | null, prev: number | null, better: "up" | "down" | "neutral", stablePct: number, fmt: (v: number) => string, nCur: number, nPrev: number, minN: number) => {
    if (cur === null || prev === null || nCur < minN || nPrev < minN) { skipped.push(label); return; }
    const ch = ((cur - prev) / prev) * 100;
    const stable = Math.abs(ch) < stablePct;
    const up = ch > 0;
    const verdict = stable ? "stable" : better === "neutral" ? (up ? "improving" : "declining") : (up === (better === "up") ? "improving" : "declining");
    rows.push({ id, label, verdict, neutral: better === "neutral", detail: `${fmt(cur)} vs ${fmt(prev)} (${ch >= 0 ? "+" : "−"}${Math.abs(ch).toFixed(1)}%)` });
  };
  const win = <T extends { date: string }>(a: T[], from: number, to: number) => a.filter((x) => inWin(x.date, today, from, to));
  const d28 = win(ds.days, 28, 0), p28 = win(ds.days, 56, 28);
  const r28 = win(ds.runs, 28, 0), rp28 = win(ds.runs, 56, 28);

  cmp("pace", "Average running pace", aggregatePace(r28), aggregatePace(rp28), "down", 1, (v) => `${fmtPace(v)} /km`, r28.length, rp28.length, 3);
  cmp("vo2", "VO₂ max (watch estimate)", mean(d28.map((d) => d.vo2max)), mean(p28.map((d) => d.vo2max)), "up", 1, (v) => v.toFixed(1), present(d28.map((d) => d.vo2max)).length, present(p28.map((d) => d.vo2max)).length, 2);
  cmp("rhr", "Resting heart rate", mean(d28.map((d) => d.restingHr)), mean(p28.map((d) => d.restingHr)), "down", 1.5, (v) => `${v.toFixed(1)} bpm`, present(d28.map((d) => d.restingHr)).length, present(p28.map((d) => d.restingHr)).length, 10);
  cmp("hrv", "Heart-rate variability", mean(d28.map((d) => d.hrv)), mean(p28.map((d) => d.hrv)), "up", 3, (v) => `${v.toFixed(0)} ms`, present(d28.map((d) => d.hrv)).length, present(p28.map((d) => d.hrv)).length, 10);
  cmp("sleep", "Sleep duration", mean(d28.map((d) => d.sleepMin)), mean(p28.map((d) => d.sleepMin)), "up", 2, (v) => `${(v / 60).toFixed(1)} h`, present(d28.map((d) => d.sleepMin)).length, present(p28.map((d) => d.sleepMin)).length, 10);
  const prot = (a: typeof d28) => a.filter((d) => isCompleteNutritionDay(d, today)).map((d) => d.protein);
  cmp("protein", "Protein intake", mean(prot(d28)), mean(prot(p28)), "up", 3, (v) => `${v.toFixed(0)} g`, present(prot(d28)).length, present(prot(p28)).length, 10);
  const km = (a: typeof r28) => a.reduce((x, r) => x + r.distanceKm, 0) / 4;
  if (r28.length >= 3 && rp28.length >= 3) cmp("km", "Weekly running distance", km(r28), km(rp28), "neutral", 5, (v) => `${v.toFixed(1)} km/wk`, r28.length, rp28.length, 3);
  else skipped.push("Weekly running distance");
  const w = sortedWeights(ds.weights);
  const wc = win(w, 14, 0), wp = win(w, 42, 28);
  cmp("weight", "Body weight (manual)", mean(wc.map((x) => x.kg)), mean(wp.map((x) => x.kg)), "neutral", 0.5, (v) => `${v.toFixed(1)} kg`, wc.length, wp.length, 2);
  return { rows, skipped };
}
